import {escapeHtml as esc} from './components.js';
import {safeLink,updated} from './research-view.js';
const fmt=n=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:2}):'—';
export function chart(points,label,value,unit,metric='revenue'){
 const vals=points.map(value),valid=vals.filter(Number.isFinite);if(!valid.length)return `<article class="financial-chart"><h3>${label}</h3><p>표시할 분기 자료가 없습니다</p></article>`;
 const min=Math.min(0,...valid),max=Math.max(0,...valid),y=v=>24+140*(max-v)/(max-min||1),x=i=>64+i*490/Math.max(1,points.length-1),largest=Math.max(...valid.map(Math.abs)),scale=unit==='KRW'&&largest>=1e12?1e12:largest>=1e9?1e9:largest>=1e6?1e6:1;
 return `<article class="financial-chart"><h3>${label} <small>${scale===1e12?'조 ':scale===1e9?'십억 ':scale===1e6?'백만 ':''}${esc(unit)}</small></h3><svg viewBox="0 0 600 210" role="img" aria-label="${label} 최근 ${points.length}분기 추이"><line class="financial-zero" x1="60" x2="560" y1="${y(0)}" y2="${y(0)}"/>${[min,max].map(v=>`<text x="56" y="${y(v)+4}" text-anchor="end">${fmt(v/scale)}</text>`).join('')}${points.map((p,i)=>{const v=vals[i];return `${i&&Number.isFinite(v)&&Number.isFinite(vals[i-1])&&p.metrics[metric]?.source?.basis===points[i-1].metrics[metric]?.source?.basis?`<line x1="${x(i-1)}" y1="${y(vals[i-1])}" x2="${x(i)}" y2="${y(v)}" stroke="#148b80" stroke-width="2"/>`:''}${Number.isFinite(v)?`<circle tabindex="0" cx="${x(i)}" cy="${y(v)}" r="3" fill="#148b80"><title>${esc(p.label)} · ${esc(p.metrics[metric]?.source?.basis||'기준 미확인')} · ${fmt(v)} ${esc(unit)}</title></circle>`:''}${i%3===0||i===points.length-1?`<text x="${x(i)}" y="193" text-anchor="middle">${esc(p.end.slice(2,7))}</text>`:''}`;}).join('')}</svg></article>`;
}
export function renderEarningsFlow(result,open=false){
 const f=result?.flow;
 if(!f)return `<section id="earnings-flow" class="earnings-flow"><h3>실적 추이</h3><p role="status">${esc(result?.status==='unavailable'?'분기 재무를 불러오지 못했습니다. 다시 확인해 주세요.':'최근 분기 공시 재무 확인 중…')}</p>${result?.status==='unavailable'?'<button data-flow-retry>다시 확인</button>':''}</section>`;
 const points=f.points||[],currency=points.at(-1)?.metrics.revenue.unit||'',basis=(f.basis||[]).map(b=>b==='OFS'?'별도재무제표':b==='CFS'||b==='consolidated'?'연결재무제표':b).join(' / ');
 const evidence=!f.stale?['매출 YoY','영업이익률'].map(label=>(f.evidence||[]).find(e=>e.label===label)).filter(Boolean):[];
 return `<section id="earnings-flow" class="earnings-flow"><details ${open?'open':''}><summary><span class="earnings-flow-heading"><strong>실적 추이</strong><small>${esc(f.quarter||'분기 미확인')}</small><span class="earnings-flow-toggle">상세 보기 ↕</span></span>${evidence.length?`<span class="earnings-flow-facts">${evidence.map(e=>`<span title="${esc(e.period)}">${esc(e.text)}</span>`).join('')}</span>`:''}</summary><div class="earnings-flow-expanded"><p>${esc(basis)} · 확보 ${points.length}분기${f.stale?' · 갱신 지연, 마지막 저장 자료':''}</p><div class="financial-chart-grid">${chart(points,'매출 성장률 (YoY)',p=>p.revenueYoy,'%')}${chart(points,'영업이익률',p=>p.margin,'%')}${chart(points,'영업현금흐름',p=>p.metrics.operatingCashFlow.value,currency,'operatingCashFlow')}${chart(points,'잉여현금흐름',p=>p.metrics.freeCashFlow.value,currency,'freeCashFlow')}</div><p class="research-note">결측·연결/별도 기준 변경 구간은 연결하지 않습니다.</p><div class="earnings-flow-periods">${points.slice().reverse().map(p=>`<details><summary>${esc(p.label)}</summary><p>매출 YoY ${fmt(p.revenueYoy)}% · QoQ ${fmt(p.metrics.revenue.qoq)}% / 영업이익률 ${fmt(p.margin)}%</p><p>영업현금흐름 ${fmt(p.metrics.operatingCashFlow.value)} ${esc(currency)} · 전년 동기 대비 ${fmt(p.metrics.operatingCashFlow.yoyChange)} ${esc(currency)}</p><p>EPS ${fmt(p.metrics.eps.value)} ${esc(p.metrics.eps.unit||'')} · 전년 동기 대비 ${fmt(p.metrics.eps.yoyChange)}</p><p>${[...new Map(Object.values(p.metrics).map(m=>m.source).filter(s=>s?.url).map(s=>[s.accession,s])).values()].map(s=>`발표일 ${esc(s.filedAt)} · ${esc(s.basis)} <a href="${safeLink(s.url)}" target="_blank" rel="noopener noreferrer">공시 원문 ↗</a>`).join(' · ')}</p></details>`).join('')}</div><details class="earnings-flow-method"><summary>비교 기준·공시 원문</summary>${(f.evidence||[]).map(e=>`<p>${esc(e.text)}<small> ${esc(e.period)}</small></p>`).join('')}<p>매출 YoY는 직전 분기의 YoY와 비교하고, 이익률·현금흐름은 전년 동기와 비교합니다. 이익률 차이는 %p이며 음수 기저에 증가율을 만들지 않습니다.</p>${f.sources.map(s=>`<p>발표일 ${esc(s.filedAt)} · <a href="${safeLink(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.form||s.accession)} 원문 ↗</a></p>`).join('')||'<p>공시 원문 미확인</p>'}<p>갱신 ${esc(updated(f.updatedAt))}</p></details></div></details></section>`;
}
